<span class="line"><span style="color:#F97583;">    lg</span><span style="color:#E1E4E8;"> = log --graph --</span><span style="color:#F97583;">pretty</span><span style="color:#E1E4E8;">=format:</span><span style="color:#9ECBFF;">&#39;%Cred%h%Creset -%C(yellow)%d%Creset %s %Cgreen(%cr) %C(bold blue)&lt;%an&gt;%Creset&#39;</span><span style="color:#E1E4E8;"> --abbrev-commit --</span><span style="color:#F97583;">date</span><span style="color:#E1E4E8;">=relative</span></span>
